import { traverseFields } from 'payload';
/** Remove pure virtual fields from document data at every schema depth. */ export function removeVirtualFields(data, fields, config) {
    traverseFields({
        callback: ({ field, ref })=>{
            if ('name' in field && field.name && 'virtual' in field && field.virtual === true) {
                delete ref[field.name];
            }
        },
        config,
        fields,
        fillEmpty: false,
        ref: data
    });
}
